using AppCondominio.Modules.Governance.Domain;
namespace AppCondominio.Modules.Governance.Application;
public interface IGovernanceRepository{Task AddAsync<T>(T entity,CancellationToken ct) where T:class;Task<Assembly?> GetAssemblyAsync(Guid id,CancellationToken ct);Task<Motion?> GetMotionAsync(Guid id,CancellationToken ct);Task<CoexistenceCase?> GetCaseAsync(Guid id,CancellationToken ct);Task<GovernanceKpi> GetKpiAsync(Guid communityId,CancellationToken ct);Task SaveChangesAsync(CancellationToken ct);}
public sealed class GovernanceService(IGovernanceRepository repository)
{
 public async Task<Guid> CreateAssemblyAsync(Guid communityId,string title,DateTimeOffset scheduledAt,decimal quorumPercent,CancellationToken ct){var x=Assembly.Create(communityId,title,scheduledAt,quorumPercent);await repository.AddAsync(x,ct);await repository.SaveChangesAsync(ct);return x.Id;} public async Task OpenAssemblyAsync(Guid id,int eligible,int present,CancellationToken ct){var x=await repository.GetAssemblyAsync(id,ct)??throw new KeyNotFoundException("Assembly not found.");x.Open(eligible,present);await repository.SaveChangesAsync(ct);} public async Task CloseAssemblyAsync(Guid id,CancellationToken ct){var x=await repository.GetAssemblyAsync(id,ct)??throw new KeyNotFoundException("Assembly not found.");x.Close();await repository.SaveChangesAsync(ct);}
 public async Task<Guid> AddMotionAsync(Guid assemblyId,string title,CancellationToken ct){var a=await repository.GetAssemblyAsync(assemblyId,ct)??throw new KeyNotFoundException("Assembly not found.");if(a.Status!=AssemblyStatus.Open)throw new InvalidOperationException("Assembly must be open.");var x=Motion.Create(a.CommunityId,a.Id,title);await repository.AddAsync(x,ct);await repository.SaveChangesAsync(ct);return x.Id;} public async Task VoteAsync(Guid motionId,VoteChoice choice,CancellationToken ct){var x=await repository.GetMotionAsync(motionId,ct)??throw new KeyNotFoundException("Motion not found.");x.RegisterVote(choice);await repository.SaveChangesAsync(ct);} public async Task CloseMotionAsync(Guid motionId,CancellationToken ct){var x=await repository.GetMotionAsync(motionId,ct)??throw new KeyNotFoundException("Motion not found.");x.Close();await repository.SaveChangesAsync(ct);}
 public async Task<Guid> ReportCaseAsync(Guid communityId,Guid? propertyId,string category,string description,string reportedBy,CancellationToken ct){var x=CoexistenceCase.Create(communityId,propertyId,category,description,reportedBy);await repository.AddAsync(x,ct);await repository.SaveChangesAsync(ct);return x.Id;} public async Task StartReviewAsync(Guid id,CancellationToken ct){var x=await repository.GetCaseAsync(id,ct)??throw new KeyNotFoundException("Case not found.");x.StartReview();await repository.SaveChangesAsync(ct);} public async Task ResolveCaseAsync(Guid id,string resolution,decimal penaltyAmount,string? billingReference,CancellationToken ct){var x=await repository.GetCaseAsync(id,ct)??throw new KeyNotFoundException("Case not found.");x.Resolve(resolution,penaltyAmount,billingReference);await repository.SaveChangesAsync(ct);} public Task<GovernanceKpi> GetKpiAsync(Guid communityId,CancellationToken ct)=>repository.GetKpiAsync(communityId,ct);
}